225	// resolveTrailBySelector resolves a trail by an optional selector (trail
226	// number, id, or branch). An empty selector falls back to the current branch's
227	// trail. It returns an actionable error (never a nil trail with a nil error)
228	// when nothing matches, so callers can rely on a non-nil result.
229	func resolveTrailBySelector(ctx context.Context, client *api.Client, forge, owner, repo, selector, branchOverride string) (*api.TrailResource, error) {
230		selector = strings.TrimSpace(selector)
231		if selector == "" {
232			branch, err := resolveTrailBranch(ctx, branchOverride)
233			if err != nil {
234				return nil, fmt.Errorf("no trail selector given and current branch is unknown: %w\nhint: run 'entire trail list --status any' or pass a trail number, id, or branch", err)
235			}
236			found, err := findTrailByBranch(ctx, client, forge, owner, repo, branch)
237			if err != nil {
238				return nil, err
239			}
240			if found == nil {
241				return nil, fmt.Errorf("no trail found for current branch %q\nhint: run 'entire trail create' or 'entire trail list --status any'", branch)
242			}
243			return found, nil
244		}
245		found, err := findTrailBySelector(ctx, client, forge, owner, repo, selector)
246		if err != nil {
247			return nil, err
248		}
249		if found == nil {
250			return nil, fmt.Errorf("no trail %q found in %s/%s/%s (run 'entire trail list --status any')", selector, forge, owner, repo)
251		}
252		return found, nil
253	}
